cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

/**
 * Adopted readings where the specification leaves a contract open:
 *
 * - Failure contract: the spec says the CLI "exits with a non-zero status code
 *   and writes an error description to stderr". The domain layer signals this by
 *   throwing an Error with a descriptive message; the spec does not establish an
 *   error subclass, so the tests assert "throws an Error", not a specific type.
 * - "Alike" components: alike means exactly the same item type. A block applies
 *   only to a group of exactly 3 components of one type (4 runes -> no block).
 * - Rounding in the MHPCO's favour: the final premium is rounded up, the final
 *   payout is rounded down; intermediate amounts stay fractional.
 * - First insurance surcharge: 10 % of the policy base premium, applied on every
 *   quote regardless of customer history (per the integration example).
 */
describe("MHPCO Claim Office", () => {
  // --- Quote: base premiums per item type -------------------------------
  it.todo("quotes an empty item list as 5 G -- processing fee only");
  it.todo("quotes a single plain sword as 105 G -- 100 G base + 5 G fee, no other modifier");
  it.todo("quotes a single plain amulet as 65 G -- 60 G base + 5 G fee");
  it.todo("quotes a single plain staff as 85 G -- 80 G base + 5 G fee");
  it.todo("quotes a single plain potion as 45 G -- 40 G base + 5 G fee");
  it.todo("quotes a single rune as 30 G -- 25 G component base + 5 G fee");
  it.todo("quotes a single moonstone as 30 G -- 25 G component base + 5 G fee");
  it.todo("quotes a mixed policy of sword and amulet with base premium 160 G -- item base premiums are summed");

  // --- Quote: building block of 3 alike components ----------------------
  it.todo("quotes 2 runes with base premium 50 G -- no block below 3");
  it.todo("quotes 3 runes with base premium 60 G -- block of 3 alike components applies");
  it.todo("quotes 4 runes with base premium 100 G -- no block, block requires exactly 3");
  it.todo("quotes 7 runes with base premium 175 G -- no block, block requires exactly 3");
  it.todo("quotes 2 runes + 1 moonstone with base premium 75 G -- no block, different types are not alike");
  it.todo("quotes 3 runes + 3 moonstones with base premium 120 G -- two separate blocks, one per type");
  it.todo("quotes 3 moonstones with base premium 60 G -- the block rule applies per component type, not only to runes");

  // --- Quote: item-specific modifiers -----------------------------------
  it.todo("adds a 50 % curse surcharge on the cursed item's base premium -- cursed sword base 100 G -> 150 G");
  it.todo("adds a 30 % high-enchantment surcharge at enchantment exactly 5 -- sword base 100 G -> 130 G");
  it.todo("adds no high-enchantment surcharge at enchantment 4 -- sword base 100 G stays 100 G");
  it.todo("stacks curse and high-enchantment surcharges on one item -- cursed sword at enchantment 5 -> 100 + 50 + 30 = 180 G");
  it.todo("applies the curse surcharge only to the cursed item on a multi-item policy -- cursed sword + plain amulet -> 210 G before policy modifiers and fee");
  it.todo("applies the high-enchantment surcharge only to the enchanted item on a multi-item policy -- enchantment-5 sword + plain amulet -> 190 G before policy modifiers and fee");
  it.todo("applies item modifiers to component items too -- cursed rune base 25 G -> 37.5 G");

  // --- Quote: policy-wide modifiers -------------------------------------
  it.todo("applies a 20 % loyalty discount at exactly 2 years with MHPCO -- sword policy base 100 G -> 80 G");
  it.todo("applies no loyalty discount at 1 year with MHPCO -- sword policy base 100 G stays 100 G");
  it.todo("applies a 10 % first insurance surcharge on the policy base premium -- sword policy base 100 G -> 110 G");
  it.todo("applies a 15 % follow-up discount on the second quote of a scenario -- sword policy base 100 G -> -15 G on the second quote");
  it.todo("applies no follow-up discount on the first quote of a scenario");
  it.todo("applies the 15 % follow-up discount on the third quote as well -- every contract after the first");
  it.todo("computes policy-wide modifiers from the policy base premium including item surcharges -- cursed sword, 3 years, second quote -> 160 G");
  it.todo("adds the 5 G processing fee at the very end, after all discounts and surcharges");

  // --- Quote: rounding ---------------------------------------------------
  it.todo("rounds a premium of 197.5 G up to 198 G -- rounding favours the MHPCO");
  it.todo("keeps intermediate amounts fractional and rounds only the final premium");

  // --- Quote: integration examples ---------------------------------------
  it.todo("quotes the newcomer with a cursed sword as 165 G -- 100 base + 50 curse + 10 first insurance + 5 fee");
  it.todo("quotes the long-standing customer's second contract as 160 G -- 100 + 50 curse + 30 enchantment - 20 loyalty + 10 first insurance - 15 follow-up + 5 fee");

  // --- Quote: rejection ---------------------------------------------------
  it.todo("throws an Error describing the unknown item type when a quote includes {type: 'broomstick'}");

  // --- Insurance sum and cap ----------------------------------------------
  it.todo("insures a sword and an amulet with insurance sum 1600 G and cap 3200 G");
  it.todo("insures two swords with insurance sum 2000 G and cap 4000 G");
  it.todo("insures a sword and 3 runes with insurance sum 1750 G and cap 3500 G -- the block discount affects the premium only");
  it.todo("bases the cap on the unmodified insurance value -- cursed sword premium 165 G but cap 2000 G");

  // --- Claim: standard reimbursement ---------------------------------------
  it.todo("pays out 400 G for a steel sword at enchantment 3 with damage 500 G -- full reimbursement minus the 100 G deductible");
  it.todo("pays out 100 G for a rune with damage 200 G -- runes have no enchantment or material, so no special clause applies");
  it.todo("reports the remaining cap after a claim -- sword policy cap 2000 G, payout 400 G -> remainingCap 1600 G");
  it.todo("pays out 0 G when the damage amount is at or below the 100 G deductible -- damage 100 G -> payout 0 G");

  // --- Claim: special clauses ------------------------------------------------
  it.todo("reimburses damage to an item at enchantment exactly 8 at 50 % -- dragon sword, damage 1000 G -> payout 400 G");
  it.todo("reimburses a steel sword at enchantment 9 at 50 % then deducts -- damage 1000 G -> payout 400 G");
  it.todo("reimburses a dragon-material sword at enchantment 5 fully then deducts -- damage 800 G -> payout 700 G");
  it.todo("lets the 50 % enchantment rule win over full dragon reimbursement -- dragon sword at enchantment 9, damage 1000 G -> payout 400 G");
  it.todo("applies no special clause at enchantment 7 on a steel item -- sword damage 1000 G -> payout 900 G");

  // --- Claim: deductible per damage event ------------------------------------
  it.todo("applies the 100 G deductible once per damaged item -- sword 500 G and amulet 300 G -> payout 600 G");
  it.todo("treats two damage entries of the same item type as separate damages with their own deductible -- two swords insured, damages 500 G and 300 G -> payout 600 G");

  // --- Claim: cap exhaustion ---------------------------------------------------
  it.todo("caps the first claim of 1500 G on a sword policy at 1400 G with remainingCap 600 G");
  it.todo("reduces the second claim of 1500 G to the remaining cap -- payout 600 G, remainingCap 0 G");
  it.todo("pays out 0 G once the cap is exhausted -- a third claim yields payout 0 G and remainingCap 0 G");

  // --- Claim: rounding ----------------------------------------------------------
  it.todo("rounds a payout of 350.5 G down to 350 G -- rounding favours the MHPCO");

  // --- Claim: rejection ----------------------------------------------------------
  it.todo("throws an Error when a damage entry names an item not covered by the policy -- amulet damaged while only a sword is insured");
  it.todo("throws an Error when a damage entry names an unknown item type");
  it.todo("throws an Error when the damages contain more entries of a type than the policy covers -- two sword damages, one sword insured");
  it.todo("throws an Error when a damage entry has a negative amount -- amount: -200");
  it.todo("throws an Error when a claim references a step index that is not a quote");

  // --- CLI adapter ------------------------------------------------------------------
  it.todo("CLI reads the schema example from stdin and writes {results:[{premium},{payout,remainingCap}]} to stdout with exit code 0");
  it.todo("CLI exits with a non-zero status code and writes an error description to stderr for an unknown item type, writing no results to stdout");
  it.todo("CLI exits with a non-zero status code and writes an error description to stderr for an invalid claim");
});
EOF
